package com.vignesh.banking.service;
import com.vignesh.banking.dto.TransferRequest;import com.vignesh.banking.model.*;import com.vignesh.banking.repository.*;import jakarta.transaction.Transactional;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import java.math.BigDecimal;import java.util.List;
@Service public class BankingService{ private final AccountRepository accounts; private final TransactionRepository txns; private final UserRepository users; public BankingService(AccountRepository a,TransactionRepository t,UserRepository u){accounts=a;txns=t;users=u;} public List<Account> myAccounts(String email){ var u=users.findByEmail(email).orElseThrow(); return accounts.findByOwnerId(u.getId()); } public Page<Transaction> history(Long accountId,int page,int size){ return txns.findByAccountIdOrderByCreatedAtDesc(accountId,PageRequest.of(page,size)); } @Transactional public String transfer(String email,TransferRequest r){ if(r.amount()==null||r.amount().compareTo(BigDecimal.ZERO)<=0) throw new RuntimeException("Amount must be positive"); var from=accounts.findByAccountNumber(r.fromAccount()).orElseThrow(()->new RuntimeException("From account not found")); var to=accounts.findByAccountNumber(r.toAccount()).orElseThrow(()->new RuntimeException("To account not found")); if(!from.getOwner().getEmail().equals(email)) throw new RuntimeException("You can only transfer from your own account"); if(from.isFrozen()||to.isFrozen()) throw new RuntimeException("Account is frozen"); if(from.getBalance().compareTo(r.amount())<0) throw new RuntimeException("Insufficient balance"); from.setBalance(from.getBalance().subtract(r.amount())); to.setBalance(to.getBalance().add(r.amount())); accounts.save(from); accounts.save(to); Transaction t=new Transaction(); t.setFromAccount(r.fromAccount()); t.setToAccount(r.toAccount()); t.setAmount(r.amount()); t.setType("TRANSFER"); t.setAccount(from); txns.save(t); return "Transfer successful"; } }
